export const CREATE_SCHEMA_SQL: string = "CREATE TABLE `events` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer NOT NULL,\n\t`kind` text NOT NULL,\n\t`sub` text,\n\t`form` text,\n\t`name` text,\n\t`agent` text,\n\t`detail` text,\n\t`tokens` integer,\n\t`gross_tokens` integer,\n\t`node_count` integer,\n\t`model_from` text,\n\t`model_to` text,\n\tCONSTRAINT `events_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_events_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_events_kind\" CHECK(\"kind\" in ('inject', 'compaction', 'prune', 'model', 'mode'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `file_ops` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`ordinal` integer NOT NULL,\n\t`time` integer,\n\t`kind` text NOT NULL,\n\t`tool` text NOT NULL,\n\t`path` text NOT NULL,\n\t`is_error` integer DEFAULT 0 NOT NULL,\n\t`lines_added` integer DEFAULT 0 NOT NULL,\n\t`lines_removed` integer DEFAULT 0 NOT NULL,\n\t`detail` text,\n\t`hits` integer,\n\t`read_start` integer,\n\t`read_count` integer,\n\t`read_est` integer DEFAULT 0 NOT NULL,\n\t`parent_seq` integer,\n\t`program` text,\n\t`is_pattern` integer DEFAULT 0 NOT NULL,\n\tCONSTRAINT `file_ops_pk` PRIMARY KEY(`session_id`, `seq`, `ordinal`),\n\tCONSTRAINT `fk_file_ops_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_file_ops_kind\" CHECK(\"kind\" in ('read', 'write', 'search'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `fold_state` (\n\t`session_id` text PRIMARY KEY,\n\t`last_seq` integer DEFAULT -1 NOT NULL,\n\t`state_json` text NOT NULL,\n\t`updated_at` integer NOT NULL,\n\tCONSTRAINT `fk_fold_state_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `header_epochs` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer NOT NULL,\n\t`reason` text,\n\tCONSTRAINT `header_epochs_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_header_epochs_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `header_tools` (\n\t`session_id` text NOT NULL,\n\t`epoch_seq` integer NOT NULL,\n\t`ordinal` integer NOT NULL,\n\t`name` text NOT NULL,\n\t`tokens` integer NOT NULL,\n\t`plugin` text,\n\tCONSTRAINT `header_tools_pk` PRIMARY KEY(`session_id`, `epoch_seq`, `ordinal`),\n\tCONSTRAINT `fk_header_tools_session_id_epoch_seq_header_epochs_session_id_seq_fk` FOREIGN KEY (`session_id`,`epoch_seq`) REFERENCES `header_epochs`(`session_id`,`seq`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `meta` (\n\t`key` text PRIMARY KEY,\n\t`value` text NOT NULL\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `requests` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer NOT NULL,\n\t`day` text NOT NULL,\n\t`turn` integer,\n\t`step` integer,\n\t`starts_turn` integer DEFAULT 0 NOT NULL,\n\t`is_inherited` integer DEFAULT 0 NOT NULL,\n\t`system_tokens` integer DEFAULT 0 NOT NULL,\n\t`tools_tokens` integer DEFAULT 0 NOT NULL,\n\t`user_tokens` integer DEFAULT 0 NOT NULL,\n\t`inject_tokens` integer DEFAULT 0 NOT NULL,\n\t`skill_tokens` integer DEFAULT 0 NOT NULL,\n\t`assistant_tokens` integer DEFAULT 0 NOT NULL,\n\t`tool_tokens` integer DEFAULT 0 NOT NULL,\n\t`total_tokens` integer DEFAULT 0 NOT NULL,\n\t`model` text,\n\t`provider` text,\n\t`period` text,\n\t`prompt_tokens` integer,\n\t`input_tokens` integer,\n\t`cache_read_tokens` integer,\n\t`cache_write_tokens` integer,\n\t`output_tokens` integer,\n\t`reasoning_tokens` integer,\n\t`gen_ms` integer,\n\t`active_ms` integer,\n\tCONSTRAINT `requests_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_requests_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_requests_period\" CHECK(\"period\" is null or \"period\" in ('peak', 'off'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `session_tombstones` (\n\t`id` text PRIMARY KEY,\n\t`deleted_at` integer NOT NULL,\n\t`reason` text NOT NULL,\n\tCONSTRAINT \"ck_tombstone_reason\" CHECK(\"reason\" in ('missing-from-list', 'log-file-missing'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `sessions` (\n\t`id` text PRIMARY KEY,\n\t`created_at` integer NOT NULL,\n\t`cwd` text,\n\t`parent_session` text,\n\t`origin` text,\n\t`is_seeded` integer DEFAULT 0 NOT NULL,\n\t`delegation_depth` integer,\n\t`agent_preset` text,\n\t`family_root` text NOT NULL,\n\t`seed_cut_seq` integer,\n\t`created_day` text,\n\t`title` text DEFAULT '' NOT NULL,\n\t`blank` integer DEFAULT 1 NOT NULL,\n\t`last_prompt_at` integer,\n\t`updated_at` integer NOT NULL,\n\t`archived` integer DEFAULT 0 NOT NULL,\n\t`workspace_title` text,\n\t`running` integer DEFAULT 0 NOT NULL,\n\t`search_text` text DEFAULT '' NOT NULL,\n\t`model` text,\n\t`provider` text,\n\t`reasoning_effort` text,\n\t`context_window` integer,\n\t`max_output_tokens` integer,\n\t`cur_total` integer DEFAULT 0 NOT NULL,\n\t`last_user` text,\n\t`billed_tokens` integer DEFAULT 0 NOT NULL,\n\t`fold_status` text NOT NULL,\n\t`fold_error` text,\n\t`last_seq` integer DEFAULT -1 NOT NULL,\n\t`log_path` text,\n\t`log_size` integer,\n\t`log_mtime` real,\n\t`log_revision` text,\n\t`detail_rev` integer DEFAULT 0 NOT NULL,\n\t`folded_at` integer DEFAULT 0 NOT NULL,\n\tCONSTRAINT \"ck_sessions_fold_status\" CHECK(\"fold_status\" in ('pending', 'folding', 'deleting', 'ok', 'failed', 'unsupported')),\n\tCONSTRAINT \"ck_sessions_origin\" CHECK(\"origin\" is null or \"origin\" = 'subagent')\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `skill_loads` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer NOT NULL,\n\t`day` text NOT NULL,\n\t`name` text NOT NULL,\n\t`source` text NOT NULL,\n\tCONSTRAINT `skill_loads_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_skill_loads_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_skill_sources\" CHECK(\"source\" in ('invocation', 'result', 'dispatch'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `steps` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`turn` integer,\n\t`step` integer,\n\t`start_time` integer NOT NULL,\n\t`end_time` integer,\n\t`day` text NOT NULL,\n\t`request_seq` integer,\n\t`wall_ms` integer DEFAULT 0 NOT NULL,\n\t`active_ms` integer DEFAULT 0 NOT NULL,\n\t`wait_ms` integer DEFAULT 0 NOT NULL,\n\t`idle_ms` integer DEFAULT 0 NOT NULL,\n\t`tool_busy_ms` integer DEFAULT 0 NOT NULL,\n\t`ttft_ms` integer,\n\t`beats_full` integer DEFAULT 0 NOT NULL,\n\tCONSTRAINT `steps_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_steps_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `surface_nodes` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer,\n\t`cat` text NOT NULL,\n\t`tokens` integer NOT NULL,\n\t`reasoning_tokens` integer,\n\t`answer_tokens` integer,\n\t`call_tokens` integer,\n\t`imgs` integer,\n\t`form` text,\n\t`name` text,\n\t`agent` text,\n\t`tool` text,\n\t`skill` text,\n\t`is_error` integer DEFAULT 0 NOT NULL,\n\t`calls` text,\n\t`preview` text,\n\t`preview_truncated` integer DEFAULT 0 NOT NULL,\n\t`gone_seq` integer,\n\tCONSTRAINT `surface_nodes_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_surface_nodes_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_surface_cat\" CHECK(\"cat\" in ('user', 'inject', 'skill', 'assistant', 'tool'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `system_prompts` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`time` integer NOT NULL,\n\t`tokens` integer NOT NULL,\n\t`gone_seq` integer,\n\tCONSTRAINT `system_prompts_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_system_prompts_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `timing_spans` (\n\t`session_id` text NOT NULL,\n\t`span_seq` integer NOT NULL,\n\t`seq` integer NOT NULL,\n\t`start_time` integer NOT NULL,\n\t`end_time` integer NOT NULL,\n\t`kind` text NOT NULL,\n\tCONSTRAINT `timing_spans_pk` PRIMARY KEY(`session_id`, `span_seq`),\n\tCONSTRAINT `fk_timing_spans_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE,\n\tCONSTRAINT \"ck_spans_kind\" CHECK(\"kind\" in ('ttft', 'reasoning', 'text', 'toolarg', 'tools', 'other'))\n) STRICT, WITHOUT ROWID;\n\nCREATE TABLE `tool_calls` (\n\t`session_id` text NOT NULL,\n\t`seq` integer NOT NULL,\n\t`call_id` text NOT NULL,\n\t`result_seq` integer,\n\t`name` text NOT NULL,\n\t`plugin` text,\n\t`transport` integer DEFAULT 0 NOT NULL,\n\t`code_mode` integer DEFAULT 0 NOT NULL,\n\t`parent_seq` integer,\n\t`turn` integer,\n\t`step` integer,\n\t`day` text NOT NULL,\n\t`start_time` integer NOT NULL,\n\t`end_time` integer,\n\t`duration_ms` integer,\n\t`is_error` integer DEFAULT 0 NOT NULL,\n\t`status` text,\n\t`exit_code` integer,\n\t`exit_inferred` integer DEFAULT 0 NOT NULL,\n\t`signal` text,\n\t`timed_out` integer DEFAULT 0 NOT NULL,\n\t`stopped` integer DEFAULT 0 NOT NULL,\n\t`denied` integer DEFAULT 0 NOT NULL,\n\t`derived` integer DEFAULT 0 NOT NULL,\n\t`background` integer DEFAULT 0 NOT NULL,\n\t`timeout_ms` integer,\n\t`sandbox` text,\n\t`cmd` text,\n\t`cmd_truncated` integer DEFAULT 0 NOT NULL,\n\t`cmd_description` text,\n\t`cmd_cwd` text,\n\t`program` text,\n\t`out_chars` integer,\n\t`out_truncated` integer DEFAULT 0 NOT NULL,\n\t`stderr` integer DEFAULT 0 NOT NULL,\n\tCONSTRAINT `tool_calls_pk` PRIMARY KEY(`session_id`, `seq`),\n\tCONSTRAINT `fk_tool_calls_session_id_sessions_id_fk` FOREIGN KEY (`session_id`) REFERENCES `sessions`(`id`) ON DELETE CASCADE\n) STRICT, WITHOUT ROWID;\n\nCREATE INDEX `idx_events_kind` ON `events` (`session_id`,`kind`);\nCREATE INDEX `idx_file_ops_path` ON `file_ops` (`session_id`,`path`);\nCREATE INDEX `idx_file_ops_time` ON `file_ops` (`session_id`,`time`);\nCREATE INDEX `idx_header_tools_epoch` ON `header_tools` (`session_id`,`epoch_seq`);\nCREATE INDEX `idx_requests_day` ON `requests` (`day`,`session_id`);\nCREATE INDEX `idx_requests_turn` ON `requests` (`session_id`,`turn`);\nCREATE INDEX `idx_requests_model` ON `requests` (`model`);\nCREATE INDEX `idx_requests_provider` ON `requests` (`provider`);\nCREATE INDEX `idx_tombstones_deleted` ON `session_tombstones` (`deleted_at`);\nCREATE INDEX `idx_sessions_updated` ON `sessions` (`updated_at`);\nCREATE INDEX `idx_sessions_archived_updated` ON `sessions` (`archived`,`updated_at`);\nCREATE INDEX `idx_sessions_workspace` ON `sessions` (`workspace_title`);\nCREATE INDEX `idx_sessions_parent` ON `sessions` (`parent_session`);\nCREATE INDEX `idx_sessions_family` ON `sessions` (`family_root`);\nCREATE INDEX `idx_sessions_billed` ON `sessions` (`billed_tokens`);\nCREATE INDEX `idx_sessions_cur_total` ON `sessions` (`cur_total`);\nCREATE INDEX `idx_sessions_model` ON `sessions` (`model`);\nCREATE INDEX `idx_sessions_running` ON `sessions` (`running`);\nCREATE INDEX `idx_sessions_origin` ON `sessions` (`origin`);\nCREATE INDEX `idx_skill_loads_name` ON `skill_loads` (`name`,`day`);\nCREATE INDEX `idx_skill_loads_day` ON `skill_loads` (`day`,`session_id`);\nCREATE INDEX `idx_skill_loads_session` ON `skill_loads` (`session_id`,`name`);\nCREATE INDEX `idx_steps_start` ON `steps` (`session_id`,`start_time`);\nCREATE INDEX `idx_steps_day` ON `steps` (`day`);\nCREATE INDEX `idx_surface_gone` ON `surface_nodes` (`session_id`,`gone_seq`) WHERE \"surface_nodes\".\"gone_seq\" is not null;\nCREATE INDEX `idx_system_gone` ON `system_prompts` (`session_id`,`gone_seq`) WHERE \"system_prompts\".\"gone_seq\" is not null;\nCREATE INDEX `idx_spans_start` ON `timing_spans` (`session_id`,`start_time`);\nCREATE INDEX `idx_spans_seq` ON `timing_spans` (`session_id`,`seq`);\nCREATE UNIQUE INDEX `uq_tool_calls_call` ON `tool_calls` (`session_id`,`call_id`);\nCREATE INDEX `idx_tool_calls_start` ON `tool_calls` (`session_id`,`start_time`);\nCREATE INDEX `idx_tool_calls_scope_start` ON `tool_calls` (`start_time`,`seq`);\nCREATE INDEX `idx_tool_calls_day` ON `tool_calls` (`day`,`session_id`);\nCREATE INDEX `idx_tool_calls_session_name` ON `tool_calls` (`session_id`,`name`);\nCREATE INDEX `idx_tool_calls_name` ON `tool_calls` (`name`);\nCREATE INDEX `idx_tool_calls_program` ON `tool_calls` (`program`);\nCREATE INDEX `idx_tool_calls_duration` ON `tool_calls` (`duration_ms`,`seq`);"
